// Pull the uploaded screenshot off the form submission, whatever n8n named
// the binary property, and turn it into a data URL the vision model can read.
const item = $input.first();
const binary = item.binary || {};
const keys = Object.keys(binary);

if (keys.length === 0) {
  throw new Error('No screenshot was received. Check that the Screenshot field on the form is filled in.');
}

const binaryKey = keys[0];
const meta = binary[binaryKey];
const mimeType = meta.mimeType || 'image/png';

if (!mimeType.startsWith('image/')) {
  throw new Error('Uploaded file is ' + mimeType + '. Please upload a PNG, JPG or WEBP screenshot.');
}

const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const sizeKb = Math.round(buffer.length / 1024);

// Groq caps a single multimodal request at ~4 MB of base64. Fail loudly rather
// than letting the API come back with an opaque 413.
if (buffer.length > 3.5 * 1024 * 1024) {
  throw new Error('Screenshot is ' + sizeKb + ' KB. Please crop or compress it to under 3.5 MB.');
}

const imageDataUrl = 'data:' + mimeType + ';base64,' + buffer.toString('base64');

const VISION_SYSTEM = [
  'You are a meticulous QA engineer doing visual defect analysis.',
  'You are shown a single screenshot captured at the moment a bug appeared.',
  'Your job is to DESCRIBE, not to diagnose. Report only what is actually visible.',
  'Transcribe every piece of on-screen text verbatim, including error text, field',
  'labels, button captions, tooltips, badges, breadcrumbs, URLs and timestamps.',
  'If something is cut off or unreadable, say so rather than guessing.',
].join(' ');

const VISION_USER = [
  'Analyse this bug screenshot and report under these exact headings:',
  '',
  '1. SCREEN / CONTEXT - which application, page or dialog this appears to be, and',
  '   any visible URL, tab title, breadcrumb or navigation state.',
  '2. VERBATIM TEXT - every readable string on screen, quoted exactly. Error',
  '   messages, codes and stack fragments first.',
  '3. WHAT LOOKS WRONG - concrete visual anomalies: overlapping or clipped',
  '   elements, misaligned layout, empty regions that should hold data, broken',
  '   images, wrong colours or states, spinners stuck mid-load, validation styling.',
  '4. UI STATE - state of the interactive controls: which fields are filled and',
  '   with what values, which buttons are enabled or disabled, what is selected,',
  '   what is focused, any modal or overlay that is open.',
  '5. DATA VISIBLE - record identifiers, counts, totals, dates or names on screen',
  '   that a developer could use to locate the failing record.',
  '6. NOT VISIBLE - what a reader would want to know that this screenshot does not',
  '   show (for example the network tab, the preceding screen, the logged-in user).',
  '',
  'Do not speculate about source code or root cause. Do not invent text that is',
  'not legible in the image.',
].join('\n');

const visionBody = {
  model: 'meta-llama/llama-4-scout-17b-16e-instruct',
  temperature: 0.1,
  max_tokens: 2000,
  messages: [
    { role: 'system', content: VISION_SYSTEM },
    {
      role: 'user',
      content: [
        { type: 'text', text: VISION_USER },
        { type: 'image_url', image_url: { url: imageDataUrl } },
      ],
    },
  ],
};

return [{
  json: {
    ...item.json,
    binaryKey,
    fileName: meta.fileName || 'screenshot.png',
    mimeType,
    fileSizeKb: sizeKb,
    visionBody,
  },
  binary: item.binary,
}];

// Merge the vision model's description with everything the tester typed, and
// shape it into a single prompt for the drafting agent.
const vision = $input.first().json;
const analysis = vision.choices && vision.choices[0] && vision.choices[0].message
  ? vision.choices[0].message.content
  : '';

if (!String(analysis).trim()) {
  throw new Error('The vision model returned an empty analysis. Check the Groq model name and your quota.');
}

const form = $('Bug Intake Form').first().json;
const prep = $('Prepare Screenshot').first().json;

const action = form['What were you doing when this happened'] || '(not supplied)';
const logs = form['Error Logs or Console Output'] || '';
const environment = form['Environment'] || '(not supplied)';
const gutFeel = form['Severity - your gut feel'] || 'Not sure';
const reporter = form['Reporter'] || 'Unknown';

const agentPrompt = [
  'Draft a Jira bug report from the evidence below.',
  '',
  '=== WHAT THE TESTER WAS DOING ===',
  action,
  '',
  '=== VISUAL ANALYSIS OF THE SCREENSHOT ===',
  analysis,
  '',
  '=== ERROR LOGS / CONSOLE OUTPUT ===',
  logs.trim() ? logs : '(none supplied)',
  '',
  '=== ENVIRONMENT ===',
  environment,
  '',
  '=== TESTER SEVERITY GUT FEEL ===',
  gutFeel,
  '',
  'The screenshot file (' + prep.fileName + ', ' + prep.fileSizeKb + ' KB) is attached to',
  'the ticket, so refer to it as the attached screenshot rather than describing the file.',
].join('\n');

return [{
  json: {
    agentPrompt,
    visualAnalysis: analysis,
    action,
    logs,
    environment,
    gutFeel,
    reporter,
    fileName: prep.fileName,
    binaryKey: prep.binaryKey,
  },
}];

parameters.inputSchema:
{
  "type": "object",
  "required": [
    "summary",
    "affectedArea",
    "severity",
    "priority",
    "environment",
    "stepsToReproduce",
    "expectedResult",
    "actualResult",
    "visualObservations",
    "labels",
    "confidence"
  ],
  "properties": {
    "summary": {
      "type": "string",
      "description": "One-line Jira summary, under 100 characters."
    },
    "affectedArea": {
      "type": "string",
      "description": "Feature or module the defect sits in, e.g. Checkout, Login, Reports."
    },
    "severity": {
      "type": "string",
      "enum": [
        "Blocker",
        "Critical",
        "Major",
        "Minor",
        "Trivial"
      ]
    },
    "priority": {
      "type": "string",
      "enum": [
        "Highest",
        "High",
        "Medium",
        "Low",
        "Lowest"
      ]
    },
    "environment": {
      "type": "string",
      "description": "Browser, OS and app area as far as the evidence shows."
    },
    "preconditions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "State that must hold before step 1."
    },
    "stepsToReproduce": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Atomic steps, 3-7 of them, without the leading number."
    },
    "expectedResult": {
      "type": "string"
    },
    "actualResult": {
      "type": "string"
    },
    "visualObservations": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Specific things visible in the screenshot a developer would care about."
    },
    "errorAnalysis": {
      "type": "string",
      "description": "What the logs indicate. Empty string if no logs were supplied."
    },
    "suspectedRootCause": {
      "type": "string",
      "description": "Best hypothesis, always marked (inferred). Empty string if unclear."
    },
    "labels": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "openQuestions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Gaps the evidence could not close."
    },
    "confidence": {
      "type": "string",
      "enum": [
        "high",
        "medium",
        "low"
      ]
    }
  }
}

parameters.jsCode:
// Turn the agent's structured output into (a) a Jira wiki-markup description and
// (b) an HTML preview for the tester's review page.
const agent = $input.first().json.output || {};
const ctx = $('Assemble Bug Context').first().json;

const list = (arr) => (Array.isArray(arr) ? arr.filter(Boolean) : []);
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const unnumber = (s) => String(s).replace(/^\s*\d+[.)]\s*/, '');

const steps = list(agent.stepsToReproduce);
const preconditions = list(agent.preconditions);
const observations = list(agent.visualObservations);
const questions = list(agent.openQuestions);

if (steps.length === 0) {
  throw new Error('The agent produced no steps to reproduce. Re-run, or lower the model temperature.');
}

// Jira labels cannot contain spaces.
const labels = list(agent.labels)
  .concat(['ai-drafted', 'severity-' + String(agent.severity || 'unknown').toLowerCase()])
  .map((l) => String(l).trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, ''))
  .filter((l) => l.length > 0 && l.length <= 255);

const summary = String(agent.summary || 'Untitled defect').replace(/\s+/g, ' ').trim().slice(0, 250);

// ----- Jira description, wiki markup for REST API v2 -----
const d = [];
d.push('h2. Steps to Reproduce');
if (preconditions.length) {
  d.push('*Preconditions*');
  preconditions.forEach((p) => d.push('* ' + p));
  d.push('');
}
steps.forEach((s) => d.push('# ' + unnumber(s)));
d.push('');
d.push('h2. Expected Result');
d.push(agent.expectedResult || '_Not determined._');
d.push('');
d.push('h2. Actual Result');
d.push(agent.actualResult || '_Not determined._');
d.push('');
if (observations.length) {
  d.push('h2. Visual Observations (from the attached screenshot)');
  observations.forEach((o) => d.push('* ' + o));
  d.push('');
}
if (ctx.logs && ctx.logs.trim()) {
  d.push('h2. Error Logs');
  d.push('{code}');
  d.push(ctx.logs.trim().slice(0, 8000));
  d.push('{code}');
  d.push('');
  if (agent.errorAnalysis) {
    d.push('*Analysis:* ' + agent.errorAnalysis);
    d.push('');
  }
}
if (agent.suspectedRootCause) {
  d.push('h2. Suspected Root Cause _(inferred - needs developer confirmation)_');
  d.push(agent.suspectedRootCause);
  d.push('');
}
if (questions.length) {
  d.push('h2. Open Questions');
  questions.forEach((q) => d.push('* ' + q));
  d.push('');
}
d.push('h2. Environment');
d.push('|| Field || Value ||');
d.push('| Environment | ' + (agent.environment || ctx.environment) + ' |');
d.push('| Affected Area | ' + (agent.affectedArea || 'Unknown') + ' |');
d.push('| Severity | ' + (agent.severity || 'Unknown') + ' |');
d.push('| Suggested Priority | ' + (agent.priority || 'Medium') + ' |');
d.push('| Reported By | ' + ctx.reporter + ' |');
d.push('| Screenshot | ' + ctx.fileName + ' (attached) |');
d.push('');
d.push('----');
d.push('_Drafted from a screenshot by an n8n AI agent, reviewed by ' + ctx.reporter +
  ' on ' + new Date().toISOString().slice(0, 10) + '. Agent confidence: ' +
  (agent.confidence || 'unknown') + '._');

const description = d.join('\n');

// ----- HTML preview rendered on the review form -----
const h = [];
h.push('<div style="font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:1.55;color:#172b4d;text-align:left">');
h.push('<div style="background:#f4f5f7;border-left:4px solid #0052cc;padding:10px 14px;margin-bottom:14px;border-radius:3px">');
h.push('<strong style="display:block;font-size:15px;margin-bottom:4px">' + esc(summary) + '</strong>');
h.push('<span style="font-size:12px;color:#5e6c84">' + esc(agent.severity || '?') + ' &middot; ' +
  esc(agent.affectedArea || 'Unknown area') + ' &middot; agent confidence: ' + esc(agent.confidence || '?') + '</span>');
h.push('</div>');
h.push('<p style="margin:0 0 6px"><strong>Steps to reproduce</strong></p><ol style="margin:0 0 14px;padding-left:20px">');
steps.forEach((s) => h.push('<li>' + esc(unnumber(s)) + '</li>'));
h.push('</ol>');
h.push('<p style="margin:0 0 8px"><strong>Expected</strong><br>' + esc(agent.expectedResult) + '</p>');
h.push('<p style="margin:0 0 14px"><strong>Actual</strong><br>' + esc(agent.actualResult) + '</p>');
if (observations.length) {
  h.push('<p style="margin:0 0 6px"><strong>Visual observations</strong></p><ul style="margin:0 0 14px;padding-left:20px">');
  observations.forEach((o) => h.push('<li>' + esc(o) + '</li>'));
  h.push('</ul>');
}
if (questions.length) {
  h.push('<p style="margin:0 0 6px;color:#bf2600"><strong>Open questions the agent could not answer</strong></p><ul style="margin:0 0 14px;padding-left:20px;color:#bf2600">');
  questions.forEach((q) => h.push('<li>' + esc(q) + '</li>'));
  h.push('</ul>');
}
h.push('<p style="margin:0;font-size:12px;color:#5e6c84">Labels: ' + esc(labels.join(', ')) + '</p>');
h.push('</div>');

return [{
  json: {
    summary,
    description,
    labels,
    severity: agent.severity || 'Unknown',
    priority: agent.priority || 'Medium',
    affectedArea: agent.affectedArea || 'Unknown',
    confidence: agent.confidence || 'unknown',
    reviewHtml: h.join(''),
  },
}];

// Apply the tester's edits from the review page, then build the exact REST body.
const review = $input.first().json;
const draft = $('Build Jira Draft').first().json;

const override = String(review['Override the summary'] || '').trim();
const notes = String(review['Anything to add'] || '').trim();

let description = draft.description;
if (notes) {
  description = 'h2. Reviewer Notes\n{panel:bgColor=#deebff}\n' + notes + '\n{panel}\n\n' + description;
}

const payload = {
  fields: {
    project: { key: 'KAN' },
    issuetype: { name: 'Bug' },
    summary: (override || draft.summary).slice(0, 250),
    description,
    labels: draft.labels,
  },
};

return [{ json: { jiraIssuePayload: payload } }];

// Jira returns only { id, key, self } on create, with no binary attached. Pull
// the original file back off the form trigger so the upload node can send it.
const created = $input.first().json;

if (!created.key) {
  throw new Error('Jira did not return an issue key. Response: ' + JSON.stringify(created).slice(0, 500));
}

const trigger = $('Bug Intake Form').first();
const prep = $('Prepare Screenshot').first().json;

return [{
  json: {
    issueKey: created.key,
    issueUrl: 'https://myfirstaiproject.atlassian.net/browse/' + created.key,
    binaryKey: prep.binaryKey,
    fileName: prep.fileName,
  },
  binary: trigger.binary,
}];
